/* =========================================================================
 *  OPTIMIZED JAVASCRIPT - ReferGloble
 * ========================================================================= */

document.addEventListener('DOMContentLoaded', () => {
    // Cache DOM Elements
    const DOM = {
        loader: document.getElementById('loadingScreen'),
        progress: document.querySelector('.loading-progress'),
        toggle: document.getElementById('mobileToggle'),
        menu: document.getElementById('navMenu'),
        navLinks: document.querySelectorAll('.nav-links a, .nav-cta a'),
        navbar: document.getElementById('navbar'),
        backBtn: document.getElementById('backToTop'),
        revealItems: document.querySelectorAll('.feature-card-3d, .service-tilt, .timeline-card, .team-member, .portfolio-card, .service-card-3d, .stat-card'),
        statNumbers: document.querySelectorAll('.stat-number'),
        modal: document.getElementById('projectModal'),
        closeModal: document.querySelector('.close-modal'),
        portfolioCards: document.querySelectorAll('.portfolio-card'),
        form: document.getElementById('contactForm3d'),
        heroVideo: document.getElementById('heroVideo'),
        heroElements: document.querySelectorAll('.hero-title, .hero-description, .hero-buttons, .hero-badge'),
        // Cursor elements
        cursorDot: document.querySelector('.cursor-dot'),
        cursorRing: document.querySelector('.cursor-ring'),
        hoverTargets: document.querySelectorAll('a, button, .feature-card-3d, .service-tilt, .portfolio-card, .stat-card')
    };

    const PROJECTS = {
        1: {
            title: "ePrescribe – AI-powered clinic & hospital management software",
            description: "An advanced AI-driven healthcare platform designed to streamline clinic and hospital operations. ePrescribe helps doctors and medical staff manage patient records, digital prescriptions, appointments, and treatment history in one secure system. It reduces manual paperwork, improves accuracy in prescriptions, and enhances overall patient care efficiency through smart automation and AI assistance."
        },
        2: {
            title: "Smart AI parking solution for societies & corporates",
            description: "SafePark is an intelligent parking management system powered by AI that simplifies vehicle entry, exit, and space allocation. It is ideal for residential societies, corporate offices, malls, and gated communities. The system provides real-time parking availability, automated gate control, visitor tracking, and enhanced security through number plate recognition and smart monitoring."
        },
        3: {
            title: "Future Fashion",
            description: "An interactive lookbook platform that brings fashion collections to life with immersive 3D visualization and dynamic storytelling. Future Fashion allows designers to showcase their pieces in an engaging way, with customizable backgrounds, product highlights, and interactive details. Perfect for fashion brands looking to create memorable online experiences that convert browsers into buyers."
        }
    };

    // Reliable check for mobile/touch devices based on window width and hover support
    const isMobile = () => window.innerWidth <= 768 || window.matchMedia('(hover: none)').matches;

    /* ========== CUSTOM CURSOR (Optimized) ========== */
    if (DOM.cursorDot && DOM.cursorRing) {
        if (!isMobile()) {
            let mouseX = -100;
            let mouseY = -100;
            let frameScheduled = false;

            document.addEventListener('mousemove', (e) => {
                mouseX = e.clientX;
                mouseY = e.clientY;
                // Use requestAnimationFrame to avoid layout thrashing
                if (!frameScheduled) {
                    window.requestAnimationFrame(updateCursorPosition);
                    frameScheduled = true;
                }
            }, { passive: true });

            const updateCursorPosition = () => {
                // translate3d forces GPU hardware acceleration for 60fps smoothness
                DOM.cursorDot.style.transform = `translate3d(${mouseX - 2.5}px, ${mouseY - 2.5}px, 0)`;
                DOM.cursorRing.style.transform = `translate3d(${mouseX - 18}px, ${mouseY - 18}px, 0)`;
                frameScheduled = false;
            };

            // Hover effects for links and cards
            if (DOM.hoverTargets.length) {
                DOM.hoverTargets.forEach(el => {
                    el.addEventListener('mouseenter', () => {
                        DOM.cursorRing.style.width = '52px';
                        DOM.cursorRing.style.height = '52px';
                    });
                    el.addEventListener('mouseleave', () => {
                        DOM.cursorRing.style.width = '36px';
                        DOM.cursorRing.style.height = '36px';
                    });
                });
            }
        } else {
            // Hide elements completely on touch devices to save resources
            DOM.cursorDot.style.display = 'none';
            DOM.cursorRing.style.display = 'none';
        }
    }

    /* ========== LOADING SCREEN ========== */
    if (DOM.progress) DOM.progress.style.width = '100%';
    setTimeout(() => {
        if (DOM.loader) {
            DOM.loader.style.opacity = '0';
            setTimeout(() => { DOM.loader.style.display = 'none'; }, 600);
        }
    }, 1400);

    /* ========== MOBILE MENU TOGGLE ========== */
    if (DOM.toggle && DOM.menu) {
        const toggleMenu = () => {
            DOM.menu.classList.toggle('active');
            DOM.toggle.classList.toggle('open');
        };
        const closeMenu = () => {
            DOM.menu.classList.remove('active');
            DOM.toggle.classList.remove('open');
        };

        DOM.toggle.addEventListener('click', toggleMenu);
        DOM.navLinks.forEach(link => link.addEventListener('click', closeMenu));
        
        document.addEventListener('click', (e) => {
            if (!e.target.closest('.navbar')) closeMenu();
        });
    }

    /* ========== SMOOTH SCROLL ========== */
    document.querySelectorAll('a[href^="#"]').forEach(anchor => {
        anchor.addEventListener('click', function(e) {
            const targetId = this.getAttribute('href');
            if (targetId === '#') return;
            const target = document.querySelector(targetId);
            if (target) {
                e.preventDefault();
                target.scrollIntoView({ behavior: 'smooth', block: 'start' });
            }
        });
    });

    /* ========== UNIFIED SCROLL HANDLER (Optimized) ========== */
    let isScrolling = false;

    const onScroll = () => {
        const scrollY = window.scrollY;
        if (DOM.navbar) {
            DOM.navbar.style.background = scrollY > 50 ? 'rgba(3,5,10,0.98)' : 'rgba(3,5,10,0.85)';
        }
        if (DOM.backBtn) {
            DOM.backBtn.style.display = scrollY > 500 ? 'flex' : 'none';
        }
        isScrolling = false;
    };

    window.addEventListener('scroll', () => {
        if (!isScrolling) {
            window.requestAnimationFrame(onScroll);
            isScrolling = true;
        }
    }, { passive: true });

    /* ========== ANIMATED COUNTERS ========== */
    const animateCounter = (el, target, duration = 2000) => {
        let startTime = null;
        const easeOutQuad = t => t * (2 - t);

        const step = (timestamp) => {
            if (!startTime) startTime = timestamp;
            const progress = Math.min((timestamp - startTime) / duration, 1);
            el.textContent = Math.floor(target * easeOutQuad(progress));

            if (progress < 1) {
                window.requestAnimationFrame(step);
            } else {
                el.textContent = target;
            }
        };
        window.requestAnimationFrame(step);
    };

    if (DOM.statNumbers.length) {
        const counterObserver = new IntersectionObserver((entries, observer) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    const el = entry.target;
                    const target = parseInt(el.dataset.target, 10);
                    if (target) animateCounter(el, target);
                    observer.unobserve(el);
                }
            });
        }, { threshold: 0.3, rootMargin: '50px' });

        DOM.statNumbers.forEach(num => counterObserver.observe(num));
    }

    /* ========== SCROLL REVEAL ANIMATION ========== */
    if (DOM.revealItems.length) {
        const revealObserver = new IntersectionObserver((entries, observer) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    entry.target.classList.add('visible');
                    observer.unobserve(entry.target); 
                }
            });
        }, { threshold: 0.15, rootMargin: '0px 0px -40px 0px' });

        DOM.revealItems.forEach(el => {
            el.classList.add('fade-in-scroll');
            revealObserver.observe(el);
        });
    }

    /* ========== BACK TO TOP CLICK ========== */
    if (DOM.backBtn) {
        DOM.backBtn.addEventListener('click', () => {
            window.scrollTo({ top: 0, behavior: 'smooth' });
        });
    }

    /* ========== PORTFOLIO MODAL ========== */
    if (DOM.modal) {
        const openProjectModal = (projectId) => {
            const project = PROJECTS[projectId];
            if (!project) {
                console.warn(`Project ${projectId} not found in projects object`);
                return;
            }
            const titleElement = DOM.modal.querySelector('h2');
            const descriptionElement = DOM.modal.querySelector('p');
            if (titleElement) titleElement.textContent = project.title;
            if (descriptionElement) descriptionElement.textContent = project.description;
            DOM.modal.classList.add('active');
            document.body.style.overflow = 'hidden';
        };
        const closeProjectModal = () => {
            DOM.modal.classList.remove('active');
            document.body.style.overflow = 'auto';
        };
        DOM.portfolioCards.forEach(card => {
            card.addEventListener('click', (e) => {
                const projectId = e.target.closest('.portfolio-card')?.getAttribute('data-project');
                console.log('Clicked portfolio card project id:', projectId);
                if (projectId) openProjectModal(projectId);
            });
        });
        if (DOM.closeModal) {
            DOM.closeModal.addEventListener('click', closeProjectModal);
        }
        window.addEventListener('click', (e) => {
            if (e.target === DOM.modal) closeProjectModal();
        });
        document.addEventListener('keydown', (e) => {
            if (e.key === 'Escape' && DOM.modal.classList.contains('active')) closeProjectModal();
        });
    }

    /* ========== CONTACT FORM VALIDATION ========== */
    if (DOM.form) {
        DOM.form.addEventListener('submit', (e) => {
            e.preventDefault();
            const nameEl = document.getElementById('contactName');
            const emailEl = document.getElementById('contactEmail');
            const feedback = document.getElementById('formFeedback');
            
            const name = nameEl ? nameEl.value.trim() : '';
            const email = emailEl ? emailEl.value.trim() : '';

            if (!name || !email || !email.includes('@')) {
                if (feedback) feedback.innerHTML = '<span style="color:#ff5e5e;">Please fill valid name & email.</span>';
            } else {
                if (feedback) feedback.innerHTML = '<span style="color:#00ffaa;">✓ Message received. We\'ll orbit back soon.</span>';
                DOM.form.reset();
            }
        });
    }

    /* ========== HERO VIDEO AUTOPLAY ========== */
    if (DOM.heroVideo) {
        DOM.heroVideo.play().catch(() => {
            console.log('Autoplay prevented by browser');
        });
    }

    /* ========== HERO TEXT FADE-IN ANIMATION ========== */
    if (DOM.heroElements.length) {
        DOM.heroElements.forEach((el, idx) => {
            el.style.opacity = '0';
            el.style.transform = 'translateY(30px)';
            el.style.transition = `opacity 0.8s ease ${idx * 0.15}s, transform 0.8s ease ${idx * 0.15}s`;
            setTimeout(() => {
                el.style.opacity = '1';
                el.style.transform = 'translateY(0)';
            }, 200);
        });
    }

    /* ========== RESPONSIVE HANDLING ========== */
    let resizeTimer;
    window.addEventListener('resize', () => {
        clearTimeout(resizeTimer);
        resizeTimer = setTimeout(() => {
            if (!isMobile() && DOM.menu && DOM.toggle) {
                DOM.menu.classList.remove('active');
                DOM.toggle.classList.remove('open');
            }
        }, 250);
    }, { passive: true });
});
